(()=>{'use strict';
const q=(s)=>document.querySelector(s),qa=(s)=>[...document.querySelectorAll(s)];
q('.motion-toggle')?.addEventListener('click',e=>{const b=e.currentTarget;const paused=document.body.classList.toggle('motion-paused');b.setAttribute('aria-pressed',String(paused));b.textContent=paused?b.dataset.resume:b.dataset.pause;});
const menu=q('.mobile-menu'),toggle=q('.menu-toggle');
function closeMenu(){if(!menu)return;menu.hidden=true;toggle.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open');}
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));menu.hidden=!open;document.body.classList.toggle('menu-open',open);if(open)menu.querySelector('a')?.focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu&&!menu.hidden){closeMenu();toggle.focus();}if(e.key==='Tab'&&menu&&!menu.hidden){const items=[toggle,...menu.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
menu?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));
const art=q('.hero-art'),caption=q('.art-mark');
qa('.art-controls button').forEach(b=>b.addEventListener('click',()=>{art.dataset.scene=b.dataset.scene;qa('.art-controls button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));caption.textContent=b.dataset.caption;}));
qa('.filter').forEach(b=>b.addEventListener('click',()=>{qa('.filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;qa('.archive-grid .work-card').forEach(c=>{c.hidden=b.dataset.filter!=='all'&&!c.dataset.tags.split(' ').includes(b.dataset.filter);if(!c.hidden)count++;});const status=q('.filter-count');if(status)status.textContent=count+' '+status.dataset.label;}));
qa('.case-view-controls button').forEach(b=>b.addEventListener('click',()=>{qa('.case-view-controls button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));qa('[data-case-panel]').forEach(p=>p.hidden=p.dataset.casePanel!==b.dataset.view);}));
const form=q('.brief-form');form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),en=document.documentElement.lang==='en';const needs=data.getAll('need').join(', ');const body=[(en?'Name: ':'Nombre: ')+data.get('name'),(en?'Company: ':'Empresa: ')+data.get('company'),(en?'Email: ':'Email: ')+data.get('email'),(en?'Interested in: ':'Nos interesa: ')+needs,'',data.get('brief')].join('\n');const href='mailto:info@backstory.com.ar?subject='+encodeURIComponent((en?'New project — ':'Nuevo proyecto — ')+(data.get('company')||data.get('name')))+'&body='+encodeURIComponent(body);const status=q('.form-status');status.replaceChildren();status.append(document.createTextNode(en?'Your brief is ready. Open your email app to review and send it. ':'Tu brief está listo. Abrí tu aplicación de correo para revisarlo y enviarlo. '));const link=document.createElement('a');link.href=href;link.textContent=en?'Open email →':'Abrir correo →';status.append(link);status.hidden=false;status.focus();});
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('js');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');observer.unobserve(e.target);}}),{threshold:.06});qa('.reveal').forEach(el=>observer.observe(el));}
const progress=q('.reading-progress');if(progress){let queued=false;window.addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%';queued=false;});}},{passive:true});}
})();
